/**
 * Moving between the auth screens (src/app/(auth)/*).
 *
 * Paths go through Href casts: the typed-routes file is generated by Metro and lags behind
 * routes added in the same change.
 */
import { useEffect } from 'react';
import { router, type Href } from 'expo-router';
import { takeLaunchAuthLink } from './logic/pendingLink';

export const AUTH_PATHS = {
  instance: '/instance',
  signIn: '/sign-in',
  register: '/register',
  verifyEmail: '/verify-email',
  forgotPassword: '/forgot-password',
  resetPassword: '/reset-password',
} as const;

export type AuthPath = (typeof AUTH_PATHS)[keyof typeof AUTH_PATHS];

function withParams(path: string, params?: Record<string, string | undefined>): string {
  const q = Object.entries(params ?? {})
    .filter(([, v]) => v !== undefined && v !== '')
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v!)}`)
    .join('&');
  return q ? `${path}?${q}` : path;
}

export function pushAuth(path: AuthPath, params?: Record<string, string | undefined>): void {
  router.push(withParams(path, params) as Href);
}

export function replaceAuth(path: AuthPath, params?: Record<string, string | undefined>): void {
  router.replace(withParams(path, params) as Href);
}

/**
 * Go back to `path` if it is below in the stack, else replace this screen with it - so moving
 * between sign-in, register and the instance screen never piles up duplicates.
 */
export function returnToAuth(path: AuthPath, params?: Record<string, string | undefined>): void {
  router.dismissTo(withParams(path, params) as Href);
}

export function backOr(path: AuthPath): void {
  if (router.canGoBack()) router.back();
  else router.replace(path as Href);
}

/**
 * On the screens the boot gate lands on (sign-in, instance): open the email link that
 * launched the app, if any (logic/pendingLink.ts).
 */
export function useLaunchAuthLink(): void {
  useEffect(() => {
    let alive = true;
    void takeLaunchAuthLink().then((link) => {
      if (!alive || !link) return;
      pushAuth(link.kind === 'verify-email' ? AUTH_PATHS.verifyEmail : AUTH_PATHS.resetPassword, {
        token: link.token,
        instance: link.instance ?? undefined,
      });
    });
    return () => {
      alive = false;
    };
  }, []);
}
